// 1. Obtener el contenido del mensaje del modelo de IA.
// Esta es la cadena de texto que puede venir con "```json" al inicio.
let content = $input.item.json.output;

// 2. Limpiar la cadena de texto.
// Este comando elimina el bloque de código Markdown "```json" del inicio 
// y "```" del final. Si no los encuentra, no hace nada. 
// Por eso funciona para ambos casos (cuando la salida es correcta y cuando no).
const cleanedString = content.replace(/^```json\s*/, '').replace(/\s*```$/, '');

// 3. Convertir (parsear) la cadena limpia a un objeto JSON real.
// Esto transforma el texto en datos que los siguientes nodos pueden entender.
const finalJson = JSON.parse(cleanedString);

// 4. Devolver el objeto JSON limpio como salida de este nodo.
return finalJson;
